#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string s;
    cin >> s;
    int winpars = 0, longest = 0;
    int i = 0, j = 0;

    // Replace all "__" with "_"
    while (s.find("__") != string::npos) {
        size_t pos;
        while ((pos = s.find("__")) != string::npos) {
            s.replace(pos, 2, "_");
        }
    }

    n = (int)s.length();

    // Process first parentheses block
    if (i < n && s[i] == '(') {
        while (j < n && s[j] != ')') {
            j++;
        }
        if (j < n && s[j] == ')') {
            string temp = s.substr(i + 1, j - i - 1);
            if (temp.find('_') == string::npos && (int)temp.length() > 0) {
                ++winpars;
            } else {
                int countTokens = 0;
                size_t start = 0;
                for (size_t k = 0; k <= temp.length(); ++k) {
                    if (k == temp.length() || temp[k] == '_') {
                        if (k > start) {
                            countTokens++;
                        }
                        start = k + 1;
                    }
                }
                winpars += countTokens;
            }
            i = j;
        }
    }

    // Process subsequent parentheses blocks
    while (i < n) {
        if (s[i] != '(') {
            ++i;
            continue;
        }
        j = i;
        while (j < n && s[j] != ')') {
            j++;
        }
        if (j < n && s[j] == ')') {
            string temp = s.substr(i + 1, j - i - 1);
            if (temp.find('_') == string::npos && (int)temp.length() > 0) {
                ++winpars;
            } else {
                int countTokens = 0;
                size_t start = 0;
                for (size_t k = 0; k <= temp.length(); ++k) {
                    if (k == temp.length() || temp[k] == '_') {
                        if (k > start) {
                            countTokens++;
                        }
                        start = k + 1;
                    }
                }
                winpars += countTokens;
            }
            i = j;
        } else {
            break;
        }
        ++i;
    }

    // Remove nested parentheses
    while (true) {
        size_t startPos = s.find('(');
        size_t endPos = s.find(')');
        if (startPos == string::npos || endPos == string::npos || startPos > endPos) {
            break;
        }
        s.replace(startPos, endPos - startPos + 1, "_");
    }

    // Find longest segment
    stringstream ss(s);
    string token;
    while (getline(ss, token, '_')) {
        if ((int)token.length() > longest) {
            longest = token.length();
        }
    }

    cout << longest << " " << winpars << "\n";

    return 0;
}
